selector_to_html = {"a[href=\"distributed-execution.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Distributed execution<a class=\"headerlink\" href=\"#distributed-execution\" title=\"Link to this heading\">#</a></h1><p>Distributed execution extends the same programming model to genuinely sharded\nworkloads. One logical workload is split across ranks; replicated execution is\nnever presented as capacity scaling.</p>", "a[href=\"#checkpoints\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Checkpoints<a class=\"headerlink\" href=\"#checkpoints\" title=\"Link to this heading\">#</a></h2><p>Module parameters and policy participate in <code class=\"docutils literal notranslate\"><span class=\"pre\">state_dict()</span></code> save and load, and\ncheckpoint and resume stay on <code class=\"docutils literal notranslate\"><span class=\"pre\">Module.save_checkpoint()</span></code> and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Module.load_checkpoint()</span></code> rather than becoming hidden options of <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.train</span></code>.\nThe circuit builder remains application code and must be supplied when\nreconstructing the module, matching normal PyTorch module construction.</p>", "a[href=\"#named-parameter-groups\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Named parameter groups<a class=\"headerlink\" href=\"#named-parameter-groups\" title=\"Link to this heading\">#</a></h2><p>Named groups remove positional-index bookkeeping for larger circuits:</p>", "a[href=\"#module-behaviour\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module behaviour<a class=\"headerlink\" href=\"#module-behaviour\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">fq.train</span></code> is deliberately a minimal, caller-owned optimizer loop: it performs\n<code class=\"docutils literal notranslate\"><span class=\"pre\">zero_grad</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">backward</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">step</span></code>, then returns <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.TrainingResult</span></code>. Use an\nordinary PyTorch loop when the quantum module is part of a larger classical\nmodel.</p>", "a[href=\"#distributed-training\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Distributed training<a class=\"headerlink\" href=\"#distributed-training\" title=\"Link to this heading\">#</a></h2><p>Under an initialized multi-rank process group, the same module and result\nsurface automatically use the native sharded statevector runtime. Owner-sharded\nstatevector and MPS training also expose separate distributed entry points,\nwhich remain experimental. See <a class=\"reference internal\" href=\"distributed-execution.html\"><span class=\"std std-doc\">Distributed execution</span></a>.</p>", "a[href=\"#precision\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Precision<a class=\"headerlink\" href=\"#precision\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Module</span></code> owns one end-to-end precision choice through <code class=\"docutils literal notranslate\"><span class=\"pre\">PrecisionPolicy</span></code>,\nwhich determines the real parameter dtype and the complex circuit/execution\ndtype. Circuit builders that omit <code class=\"docutils literal notranslate\"><span class=\"pre\">dtype</span></code> inherit that choice, and an explicit\n<code class=\"docutils literal notranslate\"><span class=\"pre\">ExecutionOptions.precision</span></code> or circuit dtype must agree with it. The module\nfails before execution instead of silently casting.</p>", "a[href=\"#training-with-pytorch\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Training with PyTorch<a class=\"headerlink\" href=\"#training-with-pytorch\" title=\"Link to this heading\">#</a></h1><p>Execution and training are intentionally separate. A trainable program is an\n<code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Module</span></code> inside an ordinary PyTorch training loop.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
